namespace sv_439c7761b758435382f5f149571e959c.Services;

/// <summary>
/// Scoped service (per-circuit) that polls for low-stock alerts and notifies
/// all subscribed components via the OnChange event.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired when alert data changes. Subscribers MUST use InvokeAsync
    /// to marshal StateHasChanged onto the Blazor sync context.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query returning the count of items below
    /// minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begin polling every 10 seconds. Reference-counted so multiple
    /// callers can start/stop independently.
    /// </summary>
    public void StartPolling(string warehouseId, Func<string, Task<int>> fetchCount)
    {
        _subscriberCount++;
        if (_timer is not null) return; // already running

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(warehouseId, fetchCount, _cts.Token);
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount > 0) return;

        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
        _cts?.Dispose();
        _cts = null;
    }

    /// <summary>
    /// Allows the warehouse selector to restart polling with a new warehouse
    /// when the user switches sites.
    /// </summary>
    public void RestartPolling(string warehouseId, Func<string, Task<int>> fetchCount)
    {
        if (_timer is null) return; // not currently polling

        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
        _cts?.Dispose();

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(warehouseId, fetchCount, _cts.Token);
    }

    private async Task PollLoopAsync(
        string warehouseId,
        Func<string, Task<int>> fetchCount,
        CancellationToken ct)
    {
        // Fetch immediately on start
        await RefreshAsync(warehouseId, fetchCount);

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await RefreshAsync(warehouseId, fetchCount);
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task RefreshAsync(string warehouseId, Func<string, Task<int>> fetchCount)
    {
        CurrentAlertCount = await fetchCount(warehouseId);
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

