@* Interactive island embedded in the static layout. *@
@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseState> WarehouseSource
@inject InventoryAlertService AlertService

<select class="form-select form-select-sm w-auto"
        value="@_selectedId"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private string _selectedId = "WH-A";

    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    protected override void OnParametersSet()
    {
        if (Warehouse is not null)
            _selectedId = Warehouse.SelectedWarehouseId;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-A";

        var newState = new WarehouseState { SelectedWarehouseId = _selectedId };
        await WarehouseSource.NotifyChangedAsync(newState);

        // Restart polling with the new warehouse so alert counts update immediately
        AlertService.RestartPolling(_selectedId, AlertService.GetLowStockCountAsync);
    }
}

@* Displays the current low-stock alert count as a badge.
   Can be placed anywhere — sidebar, dashboard, etc. *@
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Timer fires from a non-Blazor thread — must marshal via InvokeAsync
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

