@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

@if (Warehouse is not null)
{
    <div class="card mb-4" style="max-width: 28rem;">
        <div class="card-body">
            <h5 class="card-title">@Warehouse.SelectedWarehouseName</h5>
            <p class="card-text">
                Low-stock alerts:
                <AlertBadge />
            </p>
            <p class="text-muted mb-0">
                Polling every 10 seconds. Leave this page to stop polling.
            </p>
        </div>
    </div>
}
else
{
    <p>Select a warehouse to view alerts.</p>
}

@code {
    private Action? _handler;

    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    protected override void OnInitialized()
    {
        // Subscribe so this page re-renders when alerts change
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;

        // Start polling — stops in Dispose when user navigates away
        var warehouseId = Warehouse?.SelectedWarehouseId ?? "WH-A";
        AlertService.StartPolling(warehouseId, AlertService.GetLowStockCountAsync);
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        AlertService.StopPolling();
    }
}

